// Finite cover proof for the 252 vertices of KG(10,5,3). Input is generated by check.py.
#include <algorithm>
#include <array>
#include <bit>
#include <cstdint>
#include <iostream>
#include <limits>
#include <numeric>
#include <stdexcept>
#include <tuple>
#include <vector>

using Mask = std::array<std::uint64_t, 4>;
using Cells = std::vector<unsigned>;
struct Family { int support; Mask members; };
struct Choice { int id, gain; std::uint64_t orbit; };
constexpr int small = 14;  // check.py proves the classification down to this cutoff

int gain(const Mask& a, const Mask& b) {
    int n = 0;
    for (unsigned i = 0; i < a.size(); ++i) n += std::popcount(a[i] & b[i]);
    return n;
}

struct Proof {
    std::vector<Family> families;
    unsigned long long nodes = 0;
    int minimum_demand = 252;

    void exclude(const Mask& uncovered, int count, int slots, const std::vector<int>& eligible, const Cells& cells) {
        ++nodes;
        if (!count) throw std::runtime_error("cover found");
        if (!slots) return;
        const int need = (count + slots - 1) / slots;
        minimum_demand = std::min(minimum_demand, need);
        if (need <= small) throw std::runtime_error("unclassified family could meet demand");
        std::array<int, 27> histogram{};
        std::vector<Choice> choices;
        std::vector<int> allowed;
        for (int id : eligible) {
            const auto& f = families[id];
            const int s = gain(uncovered, f.members);
            if (s <= small) continue; // future marginal gains can only decrease
            if (s < need) { allowed.push_back(id); continue; }
            ++histogram.at(s);
            std::uint64_t key = 0;
            if (f.support >= 0 && cells.size() != 10) {
                for (unsigned c : cells) key = 8 * key + std::popcount(c & unsigned(f.support));
            } else {
                // Unstructured columns follow ALL structured orbits at equal gain.
                key = (std::uint64_t{1} << 40) + id;
            }
            choices.push_back({id, s, key});
        }
        int remaining = slots, capacity = 0;
        for (int s = 26; s >= need; --s) {
            int used = std::min(remaining, histogram[s]);
            remaining -= used;
            capacity += used * s;
        }
        if (capacity + remaining * (need - 1) < count) return;
        std::sort(choices.begin(), choices.end(), [](const Choice& a, const Choice& b) {
            return std::tie(a.gain, a.orbit, a.id) < std::tie(b.gain, b.orbit, b.id);
        });
        for (std::size_t i = 0; i < choices.size();) {
            const auto leader = choices[i];
            do { allowed.push_back(choices[i++].id); }
            while (i < choices.size() && choices[i].gain == leader.gain && choices[i].orbit == leader.orbit);
            // Branch on the highest-ranked group used in a hypothetical cover.
            // Retain the entire chosen group: several of its members may be necessary.
            const auto& f = families[leader.id];
            Cells next;
            if (f.support < 0) {
                for (int p = 0; p < 10; ++p) next.push_back(1u << p);
            } else {
                for (unsigned cell : cells) {
                    if (auto in = cell & unsigned(f.support)) next.push_back(in);
                    if (auto out = cell & ~unsigned(f.support)) next.push_back(out);
                }
            }
            Mask residual;
            for (unsigned b = 0; b < residual.size(); ++b) residual[b] = uncovered[b] & ~f.members[b];
            exclude(residual, count - leader.gain, slots - 1, allowed, next);
        }
    }
};

int main() {
    Proof proof;
    int support;
    while (std::cin >> std::dec >> support) {
        Mask mask;
        for (auto& w : mask) if (!(std::cin >> std::hex >> w)) throw std::runtime_error("truncated family");
        proof.families.push_back({support, mask});
    }
    if (!std::cin.eof() || proof.families.size() != 34092) throw std::runtime_error("incomplete classification");
    std::vector<int> eligible(proof.families.size());
    std::iota(eligible.begin(), eligible.end(), 0);
    constexpr auto all = std::numeric_limits<std::uint64_t>::max();
    proof.exclude({all, all, all, (std::uint64_t{1} << 60) - 1}, 252, 12, eligible, {1023});
    std::cout << "{\"excluded_colors\":12,\"nodes\":" << proof.nodes
              << ",\"minimum_demand\":" << proof.minimum_demand << "}\n";
}
